import { Inter, Noto_Serif_KR } from "next/font/google";

export const inter = Inter({
  weight: ["400", "500", "600", "700"],
  subsets: ["latin"],
  variable: "--font-inter",
  display: "swap",
});

export const notoSerifKR = Noto_Serif_KR({
  weight: ["400", "600", "700"],
  subsets: ["latin"],
  variable: "--font-noto-serif-kr",
  display: "swap",
});

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the scroll target, normalized to 60fps. */
const OPEN_LERP = 0.14;

/**
 * Drives `--bloom-open` (0 → 1) on the referenced element based on how far
 * the viewport has scrolled through the element's own height — the pinned
 * "the bloom" section. As you scroll the pinned flower stays put while
 * `--bloom-open` rises from 0 (a closed bud, petals scaled to 0.42 and
 * rotated -8°) to 1 (fully open, petals at scale 1, rotation 0°). The
 * section's height in CSS is taller than the viewport on purpose (a sticky
 * inner), so the progress maps cleanly onto a few screens of scroll.
 *
 * The CSS fallback is `var(--bloom-open, 1)` — fully open — so without
 * JavaScript, and under reduced motion (where this hook does nothing), the
 * signature flower simply stands open. The lerp makes it scrubbable without
 * jitter: scrolling fast opens fast, scrolling slow opens slow, and
 * scrolling back up closes the flower again.
 *
 * The scroll handler is passive and only writes to a CSS custom property
 * (no layout work); the rAF loop runs only while the section is on screen
 * and the tab is visible.
 */
export function useScrollProgress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;

    el.style.setProperty("--bloom-open", "0");

    let raf = 0;
    let running = false;
    let inView = true;
    let value = 0;
    let last = 0;
    let target = 0;

    const computeTarget = () => {
      const rect = el.getBoundingClientRect();
      // Progress is how far the section's top has traveled from "just
      // entered at the bottom" to "its content has scrolled past". We pin
      // via position: sticky in CSS, so the visible flower stays fixed
      // while this number climbs.
      const total = rect.height - window.innerHeight;
      if (total <= 0) {
        target = 1;
        return;
      }
      // When the section top is at or above the viewport top, progress
      // starts; it completes when the section's bottom reaches the fold.
      const traveled = Math.min(Math.max(-rect.top, 0), total);
      target = traveled / total;
    };

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const next = value + (target - value) * OPEN_LERP * (dt / 16.7);
      if (Math.abs(next - value) < 0.0002) return;
      value = next;
      el.style.setProperty("--bloom-open", value.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      computeTarget();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onScroll = () => {
      if (inView && !document.hidden) computeTarget();
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      document.removeEventListener("visibilitychange", onVisibility);
      // hand the element back to the CSS fallback (fully open)
      el.style.removeProperty("--bloom-open");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { inter, notoSerifKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useScrollProgress } from "./hooks/useScrollProgress";

const TITLE = "NOIR";
const SCENES = [
  { ko: "사무실, 밤 11시. 블라인드 사이로 가로등 빛이 줄무늬를 만든다.", en: "The office, 11 PM. Streetlight through the blinds makes stripes." },
  { ko: "재떨이에 꽁초가 세 개. 커피는 식었다. 사건은 식지 않았다.", en: "Three butts in the ashtray. Coffee cold. The case wasn't." },
  { ko: "비가 온다. 늘 비가 온다. 이 도시에서 진실은 젖어 있다.", en: "It rains. It always rains. In this city, truth is wet." },
];

/**
 * NOIR — 느와르, 흑백 영화. Cinematic-dark entry in pure black and white:
 * venetian-blind shadows (clip-path-reveal), hard-boiled title glyphs
 * (char-split-reveal), and a pinned scene sequence (scroll-scrub-pinned).
 * Distinct from HALFLIGHT (color procedural) and REEL (warm analog).
 */
export default function NoirPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const sceneRef = useScrollProgress<HTMLDivElement>(reduced);

  useEffect(() => {
    rootRef.current?.classList.add("noir-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "noir" }, "*");
  }, []);

  return (
    <div ref={rootRef} className={`${inter.variable} ${notoSerifKR.variable} noir-root`}>
      {/* venetian-blind shadow overlay — clip-path-reveal signature */}
      <div className="noir-blinds" aria-hidden="true" />

      <div ref={revealRef} className="noir-doc">
        <header className="noir-hero">
          <p className="noir-kicker"><span lang="ko">흑백 영화</span> · BLACK AND WHITE CINEMA</p>
          <h1 className="noir-title" aria-label="NOIR 느와르">
            {TITLE.split("").map((ch, i) => (
              <span key={i} aria-hidden="true" className="noir-glyph" style={{ "--noir-i": i } as CSSProperties}>{ch}</span>
            ))}
          </h1>
          <p className="noir-title__ko" lang="ko">느와르</p>
          <p className="noir-sub"><span lang="ko">블라인드. 담배 연기. 거친 활자.</span> Venetian blinds. Cigarette smoke. Hard-boiled type.</p>
        </header>

        {/* scroll-scrub-pinned: the scene sequence */}
        <section ref={sceneRef} className="noir-scenes">
          {SCENES.map((s, i) => (
            <div key={i} className="noir-scene" data-reveal="" style={{ "--noir-scene": i } as CSSProperties}>
              <p className="noir-scene__no">{String(i + 1).padStart(2, "0")}</p>
              <p className="noir-scene__text" lang="ko">{s.ko}</p>
              <p className="noir-scene__en"><em>{s.en}</em></p>
            </div>
          ))}
        </section>

        <footer className="noir-foot" data-reveal="">
          <p>© 2026 NOIR · <span lang="ko">느와르</span> · MIT</p>
          <p><span lang="ko">끝 — 화면은 어둡다.</span> THE END — fade to black.</p>
        </footer>
      </div>
    </div>
  );
}

/* NOIR 느와르 — black and white cinema · cinematic-dark
   pure black / silver / venetian blinds · hard-boiled typography */

.noir-root {
  --noir-black: #0a0a0a;
  --noir-deep: #050505;
  --noir-silver: #e5e5e5;
  --noir-grey: #a3a3a3;
  --noir-shadow: #1a1a1a;

  position: relative;
  min-height: 100vh;
  background: var(--noir-black);
  color: var(--noir-silver);
  font-family: var(--font-inter), var(--font-noto-serif-kr), "Noto Serif KR", serif;
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.7;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Film grain — the silver-halide texture of noir stock. A static fractal
   noise laid under the blinds; no motion, a photograph does not breathe. */
.noir-root::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.35;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='g'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.9  0 0 0 0 0.9  0 0 0 0 0.9  0 0 0 0.08 0'/></filter><rect width='100%25' height='100%25' filter='url(%23g)'/></svg>");
}

.noir-root :lang(ko) { font-family: var(--font-noto-serif-kr), "Noto Serif KR", serif; }
.noir-root ::selection { background: var(--noir-silver); color: var(--noir-black); }
.noir-root :focus-visible { outline: 2px solid var(--noir-silver); outline-offset: 4px; }

/* clip-path-reveal: venetian-blind shadow overlay (the signature) */
.noir-blinds {
  position: fixed;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    transparent 0px, transparent 40px,
    rgba(0,0,0,0.4) 40px, rgba(0,0,0,0.4) 50px
  );
}
.noir-js [data-reveal] {
  clip-path: inset(0 100% 0 0);
  transition: clip-path 700ms cubic-bezier(0.16,1,0.3,1);
}
.noir-js [data-reveal].is-visible { clip-path: inset(0 0% 0 0); }
@media (prefers-reduced-motion: reduce) {
  .noir-js [data-reveal] { clip-path: none; transition: none; }
}

.noir-doc { position: relative; z-index: 1; }

/* Hero */
.noir-hero {
  padding: clamp(80px, 18vh, 160px) clamp(20px, 5vw, 60px) clamp(40px, 8vh, 80px);
  text-align: center;
}
.noir-kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  color: var(--noir-grey);
  margin: 0 0 30px;
}
.noir-title {
  font-weight: 900;
  font-size: clamp(4rem, 16vw, 11rem);
  line-height: 0.9;
  letter-spacing: 0.05em;
  margin: 0 0 8px;
  display: flex;
  justify-content: center;
  color: var(--noir-silver);
  text-shadow: 4px 4px 0 var(--noir-shadow);
}
/* char-split-reveal: hard-boiled glyph entrance */
.noir-glyph {
  display: inline-block;
  opacity: 0;
  transform: translateY(-30px) skewY(3deg);
}
.noir-js .noir-glyph {
  animation: noir-glyph-in 600ms steps(4) both;
  animation-delay: calc(var(--noir-i, 0) * 100ms + 200ms);
}
@keyframes noir-glyph-in { to { opacity: 1; transform: translateY(0) skewY(0); } }
@media (prefers-reduced-motion: reduce) {
  .noir-glyph { opacity: 1; transform: none; animation: none; }
}
.noir-title__ko {
  font-size: clamp(1rem, 2vw, 1.5rem);
  color: var(--noir-grey);
  letter-spacing: 0.4em;
  margin: 0 0 30px;
}
.noir-sub {
  color: var(--noir-grey);
  font-style: italic;
  margin: 0 auto;
  max-width: 500px;
}

/* scroll-scrub-pinned: the scene sequence */
.noir-scenes {
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
  max-width: 680px;
  margin: 0 auto;
}
.noir-scene {
  margin-bottom: clamp(60px, 12vh, 100px);
  padding-left: 60px;
  position: relative;
  border-left: 2px solid var(--noir-shadow);
}
.noir-scene__no {
  position: absolute;
  left: 0;
  top: 0;
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 900;
  color: var(--noir-grey);
  opacity: 0.4;
  transform: translateX(-50%);
  background: var(--noir-black);
  padding: 0 8px;
}
.noir-scene__text {
  font-size: clamp(1.1rem, 2.5vw, 1.5rem);
  line-height: 1.6;
  margin: 0 0 12px;
  color: var(--noir-silver);
}
.noir-scene__en {
  font-style: italic;
  color: var(--noir-grey);
  font-size: 0.95rem;
  margin: 0;
}

/* Footer */
.noir-foot {
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  text-align: center;
  border-top: 1px solid var(--noir-shadow);
  color: var(--noir-grey);
  font-size: 0.82rem;
}
.noir-foot p { margin: 0 0 6px; }
